        pos = vec2((texCoord.y-u_frameRect.y)*u_atlasSize.y, sp_size.x-(texCoord.x-u_frameRect.x)*u_atlasSize.x);
    }else{
        pos = vec2((texCoord.x-u_frameRect.x)*u_atlasSize.x, (texCoord.y-u_frameRect.y)*u_atlasSize.y);
    }

    vec2 offset = vec2(pos.x - v_offset.x, pos.y - v_offset.y);

    if(offset.x <= mask_size.x && offset.x >= 0.0 && offset.y <= mask_size.y && offset.y >= 0.0) 
