// Fragment Shader
precision mediump float;

varying vec2 v_texCoord;
uniform sampler2D u_texture;
uniform float u_wipeAmount; //Control the degree of erasure, ranging from 0 to 64
uniform vec2 pixelSize;
uniform vec4 select_color;

void main() {
    vec4 color = texture2D(u_texture, v_texCoord);
    if (color.a < 0.1) {
        return;
    }

    // Calculate the distance from the center to the current fragment
    float distanceFromCenter = abs(v_texCoord.x - 0.5) * 2.0; // Normalize to the range [0, 1]

    // Calculate transparency based on distanceFromCenter and u_wipeAmount
    float alpha = 1.0;
    if (distanceFromCenter < (u_wipeAmount / 64.0)) {
        discard;
    }

    //stroke effect
    float alphaSum = 0.0;
    if (length(select_color) > 0.0 && length(pixelSize) > 0.0) {
        for (float x = -1.0; x <= 1.0; x += 1.0) {
            for (float y = -1.0; y <= 1.0; y += 1.0) {
                if (x == 0.0 && y == 0.0) continue; 
                vec2 offset = vec2(x * pixelSize.x, y * pixelSize.y);
                vec4 neighborColor = texture2D(u_texture, v_texCoord + offset);
                alphaSum += neighborColor.a;
            }
        }
        if (alphaSum > 6.0) {
            gl_FragColor = vec4(color.rgb, color.a * alpha);
        }else{
            gl_FragColor = select_color;
        }
    }else{
gl_FragColor = vec4(color.rgb, color.a * alpha); // Apply transparency
    }
}

